<script setup lang="ts">
import { computed, ref, shallowRef, watch } from 'vue'
import { draftingApi } from '@/api'
import type { ReviewObject, ReviewSource, ReviewVariable } from '@/drafting/source-review-types'

const props=defineProps<{ projectId:string; revisionId:string; source:ReviewSource; variables:ReviewVariable[]; locale:string; disabled?:boolean }>()
const emit=defineEmits<{ question:[id:string,revisionId:string]; align:[id:string,alignment:ReviewObject]; unalign:[id:string] }>()
const t=(zh:string,en:string)=>props.locale==='en'?en:zh
type Listing=Awaited<ReturnType<typeof draftingApi.pdfSccReference>>
type Detail=Awaited<ReturnType<typeof draftingApi.pdfSccReferencePoint>>
const query=ref(''), activeQuery=ref(''), offset=ref(0), history=ref<number[]>([]), listing=shallowRef<Listing>(), detail=shallowRef<Detail>(), loading=ref(false), error=ref(''), selectedVariable=ref('')
const facts=shallowRef<Awaited<ReturnType<typeof draftingApi.pdfSccReferenceFacts>>>(), selectedFact=ref(''), selectedQuote=ref(''), alignmentReason=ref(''), alignmentAcknowledged=ref(false)
const related=shallowRef<Awaited<ReturnType<typeof draftingApi.pdfSccRelatedRules>>>(), relatedOffset=ref(0), relatedHistory=ref<number[]>([])
let generation=0
const identity=()=>[props.projectId,props.revisionId,String(props.source.id),props.source.sourceSha256].join('\n')
watch(identity,()=>{ generation++;query.value='';activeQuery.value='';offset.value=0;history.value=[];listing.value=undefined;detail.value=undefined;facts.value=undefined;related.value=undefined;relatedOffset.value=0;relatedHistory.value=[];loading.value=false;error.value='';selectedVariable.value='';selectedFact.value='';selectedQuote.value='';alignmentReason.value='';alignmentAcknowledged.value=false })
const sourceVariables=computed(()=>props.variables.filter(item=>item.status!=='excluded' && item.docIds?.some(id=>[String(props.source.id),props.source.docId,props.source.editionId].includes(String(id)))))
const variable=computed(()=>sourceVariables.value.find(item=>item.id===selectedVariable.value))
const valueType:Record<string,string>={V1:'boolean',V2:'number',V3:'text',V4:'date',V5:'choice',V6:'multiselect',V7:'record',V8:'list'}
const validFacts=computed(()=>(facts.value?.facts ?? []).filter(fact=>valueType[fact.valueType]===variable.value?.type?.kind))
const boundAnchors=computed(()=>(variable.value?.sourceAnchors ?? []).filter(anchor=>String(anchor.docId)===String(props.source.id) && anchor.sourceSha256===props.source.sourceSha256 && anchor.sourceObservationBinding?.status==='bound' && typeof anchor.text==='string'))
const quoteValid=computed(()=>!!selectedQuote.value.trim() && (!variable.value?.semanticSourceQuote || variable.value.semanticSourceQuote.includes(selectedQuote.value)) && boundAnchors.value.some(anchor=>anchor.text.includes(selectedQuote.value)))
const canAlign=computed(()=>!props.disabled && !loading.value && !!variable.value && variable.value.docIds.length===1 && String(variable.value.docIds[0])===String(props.source.id) && !variable.value.catalogAlignment?.confirmed && !variable.value.pdfReferenceAlignment?.confirmed && validFacts.value.some(fact=>fact.inputRef===selectedFact.value) && quoteValid.value && !!alignmentReason.value.trim() && alignmentAcknowledged.value)
watch(selectedVariable,()=>{selectedFact.value='';selectedQuote.value='';alignmentReason.value='';alignmentAcknowledged.value=false})
watch([selectedFact,selectedQuote],()=>{alignmentAcknowledged.value=false})
function current(token:number,key:string){return token===generation && key===identity()}
function assertIdentity(result:{ available:boolean; sourceSha256?:string }) { if(result.available && (!props.source.sourceSha256 || result.sourceSha256!==props.source.sourceSha256))throw Error(t('参考来源与当前 PDF 不一致，已停止显示。','Reference source does not match this PDF.')) }
async function load(next=0, reset=false) {
  if(loading.value)return
  const key=identity(), token=++generation, requestedQuery=reset?query.value.trim():activeQuery.value;loading.value=true;error.value='';detail.value=undefined
  try { const result=await draftingApi.pdfSccReference(props.projectId,props.revisionId,String(props.source.id),requestedQuery,next);if(!current(token,key))return;assertIdentity(result);listing.value=result;if(reset){history.value=[];activeQuery.value=requestedQuery}else if(next>offset.value)history.value=[...history.value,offset.value];offset.value=next }
  catch(caught){if(current(token,key)){listing.value=undefined;error.value=caught instanceof Error?caught.message:String(caught)}}
  finally{if(current(token,key))loading.value=false}
}
async function previous(){const prior=history.value.at(-1);if(prior===undefined)return;history.value=history.value.slice(0,-1);await load(prior)}
async function inspect(pointId:string) {
  if(loading.value)return
  const key=identity(),token=++generation;loading.value=true;error.value='';detail.value=undefined
  try { const result=await draftingApi.pdfSccReferencePoint(props.projectId,props.revisionId,String(props.source.id),pointId);if(!current(token,key))return;assertIdentity(result);detail.value=result }
  catch(caught){if(current(token,key))error.value=caught instanceof Error?caught.message:String(caught)}
  finally{if(current(token,key))loading.value=false}
}
async function loadFacts(){
  if(loading.value)return
  const key=identity(),token=++generation;loading.value=true;error.value=''
  try { const result=await draftingApi.pdfSccReferenceFacts(props.projectId,props.revisionId,String(props.source.id));if(!current(token,key))return;assertIdentity(result);facts.value=result }
  catch(caught){if(current(token,key))error.value=caught instanceof Error?caught.message:String(caught)}
  finally{if(current(token,key))loading.value=false}
}
async function loadRelated(next=0,reset=false){
  if(loading.value)return
  const key=identity(),token=++generation;loading.value=true;error.value=''
  try{const result=await draftingApi.pdfSccRelatedRules(props.projectId,props.revisionId,String(props.source.id),next);if(!current(token,key))return;assertIdentity(result);related.value=result;if(reset)relatedHistory.value=[];else if(next>relatedOffset.value)relatedHistory.value=[...relatedHistory.value,relatedOffset.value];relatedOffset.value=next}
  catch(caught){if(current(token,key)){related.value=undefined;error.value=caught instanceof Error?caught.message:String(caught)}}
  finally{if(current(token,key))loading.value=false}
}
async function previousRelated(){const prior=relatedHistory.value.at(-1);if(prior===undefined)return;relatedHistory.value=relatedHistory.value.slice(0,-1);await loadRelated(prior)}
function useSuggestion(candidate:ReviewObject){if(validFacts.value.some(fact=>fact.inputRef===candidate.inputRef)){selectedFact.value=candidate.inputRef;selectedQuote.value=String(candidate.sourceQuote ?? '')}}
function confirmAlignment(){
  if(!canAlign.value || !variable.value)return
  if(typeof crypto.randomUUID!=='function'){error.value=t('浏览器无法生成确认标识，请重试。','The browser cannot create a confirmation ID. Retry.');return}
  emit('align',variable.value.id,{status:'confirmed',confirmed:true,sourceId:String(props.source.id),sourceSha256:props.source.sourceSha256,inputRef:selectedFact.value,sourceQuote:selectedQuote.value,reason:alignmentReason.value.trim(),requestId:crypto.randomUUID(),basis:null})
}
function openVariable(){if(!props.disabled&&selectedVariable.value&&sourceVariables.value.some(item=>item.id===selectedVariable.value))emit('question',selectedVariable.value,props.revisionId)}
function rows(value:unknown):ReviewObject[]{return Array.isArray(value)?value.filter(item=>item && typeof item==='object' && !Array.isArray(item)):[]}
function unavailable(status?:string){
  if(status==='revision_source_stale_or_unknown')return t('图谱来源已变化或身份不明，请先核对当前版本。','The graph source is stale or unknown. Review the current edition first.')
  if(status==='source_not_selected'||status==='source_identity_ambiguous')return t('当前图谱未唯一选中这份 SCC 原件，请先核对来源。','This SCC source is not uniquely selected in the current graph. Review the source first.')
  if(status==='reference_missing_or_integrity_failed')return t('PDF 参考文件缺失或完整性校验失败。','The PDF reference files are missing or failed integrity verification.')
  if(status==='invalid_search')return t('搜索条件无效，请缩短文字后重试。','The search is invalid. Shorten it and try again.')
  return t('当前版次没有可用的独立 PDF 参考；不会借用 Word 版。','No independent PDF reference is available for this edition; the Word edition is not substituted.')
}
</script>

<template>
  <details class="source-note" data-pdf-scc-reference>
    <summary>{{ t('PDF 版 SCC 历史参考（待人工核对）','PDF SCC historical reference (human review required)') }}</summary>
    <p>{{ t('这套参考只针对 SHA-256 一致的 PDF 版 SCC；74 个处理点不等于 74 个变量。历史分析仍有父条和标记范围缺口，不会自动匹配变量或授权修改。请对照当前原件人工核对。','This reference applies only to the PDF SCC with the same SHA-256. Its 74 processing points are not 74 variables. Historical analysis has parent-clause and marker-range gaps; no variable match or amendment is applied automatically. Check the current source.') }}</p>
    <label>{{ t('搜索处理点或条款','Search points or clauses') }}<input v-model="query" data-pdf-scc-query maxlength="120" @keyup.enter="load(0,true)"></label><button type="button" class="btn" data-pdf-scc-search :disabled="loading" @click="load(0,true)">{{ t('读取参考','Read reference') }}</button>
    <p v-if="loading">{{ t('正在读取…','Loading…') }}</p><p v-if="error" role="alert">{{ error }}</p>
    <details><summary>{{ t('从已确认 PDF 事实查看历史关系','Review historical relationships from confirmed PDF facts') }}</summary><p>{{ t('仅显示当前已确认事实可关联到的历史分析；其余输入、分支和本版修改范围仍须核对，不会自动执行。','Only historical analysis reachable from confirmed facts is shown. Remaining inputs, branches and current amendment ranges still need review; nothing is applied automatically.') }}</p><button type="button" class="btn" data-pdf-scc-related-load :disabled="loading" @click="loadRelated(0,true)">{{ t('读取关联关系','Load related relationships') }}</button><template v-if="related"><p v-if="!related.available">{{ unavailable(related.status) }}</p><template v-else><p>{{ t('已确认事实','Confirmed facts') }}: {{ related.confirmedInputCount }} · {{ t('关联历史规则','Related historical rules') }}: {{ related.total }}</p><article v-for="rule in related.rules ?? []" :key="rule.ruleId"><strong>{{ rule.label }}</strong><p>{{ rule.relationType }} · {{ rule.impactType }} · {{ t('待核对／未绑定当前范围','Awaiting review / current range unbound') }}</p><p v-for="input in rule.inputs" :key="input.inputRef">{{ input.inputRef }} · {{ input.role }} · {{ input.stage }} · {{ input.confirmedNodeIds.length ? t('已对应','Mapped') : t('未对应，仍待核','Unmapped, review pending') }}</p><details v-for="branch in rule.branches" :key="branch.id"><summary>{{ t('历史分支','Historical branch') }} {{ branch.id }}</summary><pre>{{ JSON.stringify(branch.when,null,2) }}</pre></details><button v-for="pointId in rule.pointIds" :key="pointId" type="button" class="btn" :disabled="loading" @click="inspect(pointId)">{{ t('查看相关原文依据','Review related evidence') }} {{ pointId }}</button></article><nav><button type="button" class="btn" :disabled="loading || !relatedHistory.length" @click="previousRelated">{{ t('上一组','Previous') }}</button><button type="button" class="btn" :disabled="loading || related.nextOffset == null" @click="loadRelated(related.nextOffset!)">{{ t('下一组','Next') }}</button></nav></template></template></details>
    <template v-if="listing"><p v-if="!listing.available" data-pdf-scc-unavailable>{{ unavailable(listing.status) }}</p><template v-else><p>{{ t('历史处理点','Historical processing points') }}: {{ listing.total }} · SHA-256 {{ listing.sourceSha256 }}</p><p v-for="(limit,index) in listing.limitations ?? []" :key="index">{{ limit }}</p><article v-for="candidate in listing.candidates ?? []" :key="candidate.pointId"><strong>{{ candidate.label }}</strong><p>{{ candidate.clause }} · {{ candidate.kind }} · {{ candidate.relationStatus }}</p><p>{{ candidate.summary }}</p><button type="button" class="btn" :disabled="loading" :data-pdf-scc-point="candidate.pointId" @click="inspect(candidate.pointId)">{{ t('查看历史依据','Review historical evidence') }}</button></article><p v-if="!listing.candidates?.length">{{ t('没有符合搜索条件的处理点。','No matching processing points.') }}</p><nav><button type="button" class="btn" :disabled="loading || !history.length" @click="previous">{{ t('上一组','Previous') }}</button><button type="button" class="btn" :disabled="loading || listing.nextOffset == null" @click="load(listing.nextOffset!)">{{ t('下一组','Next') }}</button></nav></template></template>
    <section v-if="detail?.available && detail.point" data-pdf-scc-detail><h4>{{ detail.point.label }} · {{ detail.point.clause }}</h4><p>{{ detail.point.meaning }}</p><p v-if="detail.point.applicability">{{ t('历史适用性','Historical applicability') }}: {{ detail.point.applicability }}</p><p v-if="detail.point.valueSource">{{ t('历史值来源','Historical value source') }}: {{ detail.point.valueSource }}</p><p v-for="(impact,index) in detail.point.impacts ?? []" :key="index">{{ t('历史影响','Historical impact') }}: {{ impact }}</p><article v-for="(evidence,index) in detail.point.evidence ?? []" :key="index"><p>{{ t('PDF 页','PDF page') }} {{ evidence.page }}<span v-if="evidence.lineStart"> · {{ t('行','lines') }} {{ evidence.lineStart }}<template v-if="evidence.lineEnd">–{{ evidence.lineEnd }}</template></span></p><blockquote>{{ evidence.quote }}</blockquote></article><details v-if="detail.rules?.length"><summary>{{ t('历史原子规则（仅供参考）','Historical atomic rules (reference only)') }} · {{ detail.rules.length }}</summary><article v-for="(rule,index) in detail.rules" :key="index"><strong>{{ rule.label }}</strong><p>{{ rule.relationType }} · {{ rule.impactType }}</p><p v-for="(input,i) in rows(rule.inputs)" :key="i">{{ input.ref }} · {{ input.role }} · {{ input.stage }}</p><p v-for="(branch,i) in rows(rule.cases)" :key="i">{{ t('历史分支','Historical branch') }}: {{ branch.id }}</p></article></details><label v-if="sourceVariables.length">{{ t('选择当前变量进行对照','Choose a current variable to review') }}<select v-model="selectedVariable" data-pdf-scc-variable><option value="">{{ t('请选择','Choose') }}</option><option v-for="variable in sourceVariables" :key="variable.id" :value="variable.id">{{ locale==='en' ? variable.nameEn || variable.nameZh : variable.nameZh || variable.nameEn }}</option></select></label><button v-if="sourceVariables.length" type="button" class="btn" data-pdf-scc-review-variable :disabled="disabled || !selectedVariable" @click="openVariable">{{ t('打开变量人工核对','Open variable for manual review') }}</button><p v-else>{{ t('当前来源没有可核对的变量；请先识别或手工新增。','There is no current variable for this source. Identify or add one manually first.') }}</p></section>
    <section v-if="variable" data-pdf-scc-alignment><h4>{{ t('人工核对 PDF 固定事实对应','Review correspondence to a PDF fixed fact') }}</h4><p>{{ t('只确认变量含义对应；不会采用项目值或确定本版修改范围。请保存草稿并以服务器返回状态为准。','This confirms only the variable meaning. It does not adopt a project value or establish an amendment range. Save the draft and use the server-returned status.') }}</p><p v-if="variable.pdfReferenceAlignment">{{ t('已记录状态','Recorded status') }}: {{ variable.pdfReferenceAlignment.status }} · {{ variable.pdfReferenceAlignment.inputRef }} · {{ variable.pdfReferenceAlignment.reason }}</p><button v-if="variable.pdfReferenceAlignment?.confirmed" type="button" class="btn" data-pdf-scc-unalign :disabled="disabled" @click="emit('unalign',variable.id)">{{ t('撤销对应并保留历史','Revoke correspondence and retain history') }}</button><p v-if="variable.pdfReferenceSuggestions && (variable.pdfReferenceSuggestions.sourceId !== String(source.id) || variable.pdfReferenceSuggestions.sourceSha256 !== source.sourceSha256)">{{ t('模型建议来自其他来源版本，不能用于当前确认。','Model suggestions belong to another source edition and cannot be used for this confirmation.') }}</p><template v-else><article v-for="candidate in variable.pdfReferenceSuggestions?.candidates ?? []" :key="candidate.inputRef"><p>{{ t('模型建议，待人工核对','Model suggestion, requires human review') }}: {{ candidate.inputRef }} · {{ candidate.reason }}</p><blockquote>{{ candidate.sourceQuote }}</blockquote><button type="button" class="btn" :disabled="disabled || !facts?.available || !validFacts.some(fact=>fact.inputRef===candidate.inputRef)" @click="useSuggestion(candidate)">{{ t('选用建议供核对','Select suggestion for review') }}</button></article></template><button type="button" class="btn" data-pdf-scc-load-facts :disabled="loading" @click="loadFacts">{{ t('读取本版可选事实','Load facts for this edition') }}</button><p v-if="facts && !facts.available">{{ unavailable(facts.status) }}</p><template v-if="facts?.available"><p v-if="!validFacts.length">{{ t('本版没有与当前变量类型一致的可选事实。','No fact in this edition matches this variable type.') }}</p><template v-else><label>{{ t('选择对应事实','Choose the corresponding fact') }}<select v-model="selectedFact" data-pdf-scc-fact><option value="">{{ t('请选择','Choose') }}</option><option v-for="fact in validFacts" :key="fact.inputRef" :value="fact.inputRef">{{ fact.inputRef }} · {{ fact.referencePoints.map(point=>point.label).join(' / ') }}</option></select></label><p v-if="!boundAnchors.length">{{ t('当前变量没有已绑定到本版 PDF 的来源锚点。请先在原件中定位并保存来源。','This variable has no source anchor bound to this PDF. Locate and save its source first.') }}</p><template v-else><p>{{ t('从以下已绑定原文中填写与变量含义一致的原句片段。','Enter an exact passage from the bound source that supports this variable meaning.') }}</p><blockquote v-for="(anchor,index) in boundAnchors" :key="index">{{ anchor.text }}</blockquote><label>{{ t('当前变量原文片段','Exact current-source quotation') }}<textarea v-model="selectedQuote" data-pdf-scc-quote rows="2" /></label><p v-if="selectedQuote && !quoteValid">{{ t('引文必须同时出现在该变量原文与已绑定来源锚点中。','The quotation must occur in both the variable source and its bound anchor.') }}</p><label>{{ t('人工核对理由','Human review reason') }}<textarea v-model="alignmentReason" data-pdf-scc-reason rows="2" /></label><label><input v-model="alignmentAcknowledged" data-pdf-scc-acknowledged type="checkbox">{{ t('我已对照本版原件，确认变量与所选 PDF 事实含义一致。','I checked this edition and confirm the variable and selected PDF fact have the same meaning.') }}</label><button type="button" class="btn" data-pdf-scc-align :disabled="!canAlign" @click="confirmAlignment">{{ t('确认对应，待保存','Confirm correspondence and save later') }}</button></template></template></template></section>
    <p v-if="variable?.pdfReferenceAlignment?.confirmed">{{ t('如需改选，请先撤销已记录的对应并保存。','To choose another fact, first revoke the recorded correspondence and save.') }}</p><p v-if="variable?.catalogAlignment?.confirmed">{{ t('当前变量仍确认了 Word 固定目录对应；请先撤销该对应，不能混用两版。','This variable still has a confirmed Word catalog correspondence. Remove it before using the PDF edition.') }}</p><p v-if="variable && (variable.docIds.length !== 1 || String(variable.docIds[0]) !== String(source.id))">{{ t('该变量包含其他来源；请先拆分或核对来源归属。','This variable includes another source. Split it or review its source assignment first.') }}</p>
    <p v-if="detail && !detail.available">{{ t('该历史参考当前不可用。','This historical reference is unavailable.') }}</p>
  </details>
</template>
